SELECT U.id AS id,U.user_name AS userName,U.person_name AS personName,D.id AS deptId,UD.authority,D.dept_name AS deptName,D.dept_parent_id AS deptParentId,UD.id AS dept_userOfId,UD.join_time AS joinTime
FROM sys_user_dept AS UD
LEFT JOIN sys_user AS U ON UD.user_id = U.id
LEFT JOIN sys_dept AS D ON UD.dept_id = D.id


        AND (U.user_name LIKE CONCAT('%',#{queryParam.userName},'%') ESCAPE '#' OR U.person_name LIKE
        CONCAT('%',#{queryParam.userName},'%') ESCAPE '#')


        AND UD.authority = #{queryParam.authority}


        AND D.id = #{queryParam.deptId} AND D.dept_parent_id =#{queryParam.deptParentId}


        AND D.id = #{queryParam.deptId}


LIMIT #{offset}, #{validPageSize}

SELECT COUNT(*)
FROM sys_user_dept AS UD
LEFT JOIN sys_user AS U ON UD.user_id = U.id
LEFT JOIN sys_dept AS D ON UD.dept_id = D.id


        AND (U.user_name LIKE CONCAT('%',#{queryParam.userName},'%') ESCAPE '#' OR U.person_name LIKE
        CONCAT('%',#{queryParam.userName},'%') ESCAPE '#')


        AND UD.authority = #{queryParam.authority}


        AND D.id = #{queryParam.deptId} AND D.dept_parent_id =#{queryParam.deptParentId}


        AND D.id = #{queryParam.deptId}
